import java.util.*;

class Solution {
    public int fib(int n) {
        if (n < 2) return n;          // base cases: fib(0)=0, fib(1)=1
        int prev = 0, cur = 1;
        for (int i = 2; i <= n; i++) {
            int next = prev + cur;    // each term is the sum of the two before it
            prev = cur;
            cur = next;
        }
        return cur;
    }
}

